import{_ as s,c as a,o as e,a as n}from"./app.013a12f3.js";const A=JSON.parse('{"title":"Page Object Model (POM) Design Strategy for Scalable Automation Frameworks","description":"","frontmatter":{},"headers":[{"level":2,"title":"Why POM Exists","slug":"why-pom-exists","link":"#why-pom-exists","children":[]},{"level":2,"title":"Core Design Principles","slug":"core-design-principles","link":"#core-design-principles","children":[{"level":3,"title":"Single Responsibility","slug":"single-responsibility","link":"#single-responsibility","children":[]},{"level":3,"title":"Encapsulation","slug":"encapsulation","link":"#encapsulation","children":[]},{"level":3,"title":"Behavior-Oriented Methods","slug":"behavior-oriented-methods","link":"#behavior-oriented-methods","children":[]}]},{"level":2,"title":"Folder Structure","slug":"folder-structure","link":"#folder-structure","children":[]},{"level":2,"title":"Locator Strategy","slug":"locator-strategy","link":"#locator-strategy","children":[]},{"level":2,"title":"Method Design","slug":"method-design","link":"#method-design","children":[]},{"level":2,"title":"Assertions and Boundaries","slug":"assertions-and-boundaries","link":"#assertions-and-boundaries","children":[]},{"level":2,"title":"Constructor Design","slug":"constructor-design","link":"#constructor-design","children":[]},{"level":2,"title":"Reusable Components","slug":"reusable-components","link":"#reusable-components","children":[]},{"level":2,"title":"Handling Dynamic UI State","slug":"handling-dynamic-ui-state","link":"#handling-dynamic-ui-state","children":[]},{"level":2,"title":"Common POM Mistakes","slug":"common-pom-mistakes","link":"#common-pom-mistakes","children":[{"level":3,"title":"Fat page objects","slug":"fat-page-objects","link":"#fat-page-objects","children":[]},{"level":3,"title":"Selector leakage","slug":"selector-leakage","link":"#selector-leakage","children":[]},{"level":3,"title":"Generic utility abuse","slug":"generic-utility-abuse","link":"#generic-utility-abuse","children":[]},{"level":3,"title":"Mixed concerns","slug":"mixed-concerns","link":"#mixed-concerns","children":[]},{"level":3,"title":"Hardcoded test data","slug":"hardcoded-test-data","link":"#hardcoded-test-data","children":[]}]},{"level":2,"title":"Recommended Minimal Structure","slug":"recommended-minimal-structure","link":"#recommended-minimal-structure","children":[]},{"level":2,"title":"Final Takeaway","slug":"final-takeaway","link":"#final-takeaway","children":[]}],"relativePath":"blogs/page-object-model-pom-design-strategy-for-scalable-automation-frameworks.md"}'),l={name:"blogs/page-object-model-pom-design-strategy-for-scalable-automation-frameworks.md"},o=n(`<h1 id="page-object-model-pom-design-strategy-for-scalable-automation-frameworks" tabindex="-1">Page Object Model (POM) Design Strategy for Scalable Automation Frameworks <a class="header-anchor" href="#page-object-model-pom-design-strategy-for-scalable-automation-frameworks" aria-hidden="true">#</a></h1><p>Page Object Model (POM) is one of the most commonly used design patterns in UI automation, but it is also one of the most commonly misused.</p><p>The problem is not the pattern itself\u2014it is poor implementation.</p><p>A well-designed POM improves maintainability, readability, and long-term scalability. A poorly designed one creates bloated abstractions, unclear ownership, and difficult-to-maintain automation code.</p><p>The goal is not to use POM everywhere. The goal is to design it correctly when your framework needs it.</p><h2 id="why-pom-exists" tabindex="-1">Why POM Exists <a class="header-anchor" href="#why-pom-exists" aria-hidden="true">#</a></h2><p>As UI automation grows, tests often become tightly coupled to selectors and page implementation details. Example:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">locator</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">#username</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">fill</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">admin</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">locator</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">#password</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">fill</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Password123</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">locator</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">.login-btn</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">click</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This works initially, but creates problems over time:</p><ul><li>duplicated selectors across tests</li><li>difficult maintenance when UI changes</li><li>reduced test readability</li><li>fragile automation structure</li></ul><p>POM solves this by encapsulating UI behavior into reusable page abstractions.</p><p>Example:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> loginPage</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">login</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">admin</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Password123</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This creates cleaner separation between test intent and UI implementation.</p><h2 id="core-design-principles" tabindex="-1">Core Design Principles <a class="header-anchor" href="#core-design-principles" aria-hidden="true">#</a></h2><h3 id="single-responsibility" tabindex="-1">Single Responsibility <a class="header-anchor" href="#single-responsibility" aria-hidden="true">#</a></h3><p>Each page object should represent one logical page or UI responsibility.</p><p>Good examples:</p><ul><li>LoginPage</li><li>DashboardPage</li><li>CheckoutPage</li></ul><p>Avoid creating one large object for unrelated functionality.</p><p>Bad:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">ApplicationPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>This becomes difficult to maintain, debug, and scale.</p><h3 id="encapsulation" tabindex="-1">Encapsulation <a class="header-anchor" href="#encapsulation" aria-hidden="true">#</a></h3><p>Selectors should stay inside page objects.</p><p>Bad:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">locator</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">#username</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">fill</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">admin</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>Better:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> loginPage</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">enterUsername</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">admin</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>Tests should interact with page behavior, not selector implementation.</p><h3 id="behavior-oriented-methods" tabindex="-1">Behavior-Oriented Methods <a class="header-anchor" href="#behavior-oriented-methods" aria-hidden="true">#</a></h3><p>Page methods should represent meaningful user actions.</p><p>Good:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#82AAFF;">login</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">searchProduct</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">addItemToCart</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"></span></code></pre></div><p>Avoid generic wrappers like:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#82AAFF;">clickElement</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">fillInput</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">performAction</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"></span></code></pre></div><p>A good page API should reflect business intent, not low-level browser commands.</p><h2 id="folder-structure" tabindex="-1">Folder Structure <a class="header-anchor" href="#folder-structure" aria-hidden="true">#</a></h2><p>For small projects:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">pages/</span></span>
<span class="line"><span style="color:#A6ACCD;">  LoginPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">  DashboardPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">  CheckoutPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>For larger applications, organize by domain:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">pages/</span></span>
<span class="line"><span style="color:#A6ACCD;">  auth/</span></span>
<span class="line"><span style="color:#A6ACCD;">    LoginPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">    RegisterPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span>
<span class="line"><span style="color:#A6ACCD;">  commerce/</span></span>
<span class="line"><span style="color:#A6ACCD;">    ProductPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">    CartPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">    CheckoutPage.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>Feature-based organization scales better than a flat folder structure.</p><h2 id="locator-strategy" tabindex="-1">Locator Strategy <a class="header-anchor" href="#locator-strategy" aria-hidden="true">#</a></h2><p>Locator quality directly affects test stability.</p><p>Prefer stable selectors:</p><ul><li>getByRole()</li><li>getByLabel()</li><li>getByTestId()</li></ul><p>Avoid brittle selectors:</p><ul><li>nth-child</li><li>deep CSS chains</li><li>dynamic class selectors</li></ul><p>Keep locators owned by the page object:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">readonly usernameInput </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">this.</span><span style="color:#A6ACCD;">page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">getByLabel</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Username</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#A6ACCD;">readonly loginButton </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">this.</span><span style="color:#A6ACCD;">page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">getByRole</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">button</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span><span style="color:#A6ACCD;"> </span><span style="color:#F07178;">name</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Login</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This keeps maintenance localized.</p><h2 id="method-design" tabindex="-1">Method Design <a class="header-anchor" href="#method-design" aria-hidden="true">#</a></h2><p>A practical POM usually contains two method types.</p><p>Action methods for individual interactions:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#82AAFF;">enterUsername</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">clickLogin</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">selectCountry</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"></span></code></pre></div><p>Workflow methods for repeated business flows:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#82AAFF;">login</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">completeCheckout</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#82AAFF;">createOrder</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"></span></code></pre></div><p>Use workflow methods when the sequence is commonly reused.</p><p>Method naming should be explicit and readable.</p><p>Good:</p><ul><li>submitCredentials()</li><li>openCheckoutPage()</li><li>logout()</li></ul><p>Avoid vague names like:</p><ul><li>execute()</li><li>process()</li><li>handleAction()</li></ul><h2 id="assertions-and-boundaries" tabindex="-1">Assertions and Boundaries <a class="header-anchor" href="#assertions-and-boundaries" aria-hidden="true">#</a></h2><p>A common mistake is mixing assertions into every page object method.</p><p>Page objects should primarily model UI interactions.</p><p>Tests should contain business assertions. Good:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> loginPage</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">login</span><span style="color:#A6ACCD;">(user)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">expect</span><span style="color:#A6ACCD;">(dashboardPage</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">welcomeMessage)</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">toBeVisible</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This keeps responsibilities clean.</p><h2 id="constructor-design" tabindex="-1">Constructor Design <a class="header-anchor" href="#constructor-design" aria-hidden="true">#</a></h2><p>Inject dependencies explicitly.</p><p>Standard pattern:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">constructor(private page: Page) {}</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>Avoid hidden dependencies inside page objects.</p><p>Bad practices:</p><ul><li>creating API clients inside pages</li><li>loading environment config directly</li><li>instantiating unrelated services internally</li></ul><p>Page objects should stay focused on UI interaction.</p><h2 id="reusable-components" tabindex="-1">Reusable Components <a class="header-anchor" href="#reusable-components" aria-hidden="true">#</a></h2><p>Large applications often contain shared UI sections:</p><ul><li>header</li><li>sidebar</li><li>modal dialogs</li><li>search widgets</li></ul><p>These should be extracted into reusable components.</p><p>Example:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">components/</span></span>
<span class="line"><span style="color:#A6ACCD;">  HeaderComponent.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">  SidebarComponent.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>Then compose them inside page objects rather than duplicating logic.</p><h2 id="handling-dynamic-ui-state" tabindex="-1">Handling Dynamic UI State <a class="header-anchor" href="#handling-dynamic-ui-state" aria-hidden="true">#</a></h2><p>Modern UIs are asynchronous.</p><p>Your page methods should handle interaction stability responsibly.</p><p>Examples:</p><ul><li>loading states</li><li>delayed rendering</li><li>modal visibility</li><li>confirmation messages</li></ul><p>Avoid fragile timing assumptions.</p><p>Bad:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> page</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">waitForTimeout</span><span style="color:#A6ACCD;">(</span><span style="color:#F78C6C;">3000</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>Prefer deterministic waiting using Playwright locators and built-in waiting behavior.</p><h2 id="common-pom-mistakes" tabindex="-1">Common POM Mistakes <a class="header-anchor" href="#common-pom-mistakes" aria-hidden="true">#</a></h2><p>Avoid these common anti-patterns:</p><h3 id="fat-page-objects" tabindex="-1">Fat page objects <a class="header-anchor" href="#fat-page-objects" aria-hidden="true">#</a></h3><p>Too many responsibilities in one class.</p><h3 id="selector-leakage" tabindex="-1">Selector leakage <a class="header-anchor" href="#selector-leakage" aria-hidden="true">#</a></h3><p>Tests directly accessing selectors.</p><h3 id="generic-utility-abuse" tabindex="-1">Generic utility abuse <a class="header-anchor" href="#generic-utility-abuse" aria-hidden="true">#</a></h3><p>Creating meaningless wrapper methods.</p><h3 id="mixed-concerns" tabindex="-1">Mixed concerns <a class="header-anchor" href="#mixed-concerns" aria-hidden="true">#</a></h3><p>Combining UI, API, config, and assertions in one class.</p><h3 id="hardcoded-test-data" tabindex="-1">Hardcoded test data <a class="header-anchor" href="#hardcoded-test-data" aria-hidden="true">#</a></h3><p>Embedding static users or environment values inside page objects.</p><h2 id="recommended-minimal-structure" tabindex="-1">Recommended Minimal Structure <a class="header-anchor" href="#recommended-minimal-structure" aria-hidden="true">#</a></h2><p>A scalable POM-based framework can remain simple:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">framework/</span></span>
<span class="line"><span style="color:#A6ACCD;">  tests/</span></span>
<span class="line"><span style="color:#A6ACCD;">  pages/</span></span>
<span class="line"><span style="color:#A6ACCD;">  components/</span></span>
<span class="line"><span style="color:#A6ACCD;">  fixtures/</span></span>
<span class="line"><span style="color:#A6ACCD;">  utils/</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>Each folder should have a clear responsibility.</p><h2 id="final-takeaway" tabindex="-1">Final Takeaway <a class="header-anchor" href="#final-takeaway" aria-hidden="true">#</a></h2><p>POM is not about adding abstraction for the sake of architecture.</p><p>It is about creating clear boundaries between test intent and UI implementation.</p><p>A good Page Object Model makes automation easier to read, easier to maintain, and easier to scale.</p><p>A bad one becomes the problem it was meant to solve.</p>`,115),t=[o];function p(i,c,r,d,y,h){return e(),a("div",null,t)}const g=s(l,[["render",p]]);export{A as __pageData,g as default};
